1\">which pen&nbsp;</span></span></span><span style=\"font-size:16px\">কোন কলমটি&nbsp;</span><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:#111111\"><span style=\"font-size:16px\">টি</span></span></span></s","color:#111111\">whose pen = কার কলমটি / which pen = কোন কলমটি</span></span>&nbsp;</span><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:#111111\"></span></span></span><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:#111111\"></span></span></span><span style=\"font-size:16px\"></span><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:#111111\"><span style=\"font-size:16px\"></span></span></span></s"]],"331":[["tyle=\"color:black\">অনুযায়ী</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যে</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">রূপ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পরিবর্তন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">তাকে</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Finite Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">(</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সমাপিকা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ক্রিয়া) </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">বলে।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যেমন</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">: My mother cooked biryani yesterday.</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Finite Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রধান</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">এবং</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্য</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">গঠনের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ক্ষেত্রে</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">subject </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> number </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এবং</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">person </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সাহায্যে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">এই</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> form </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">নির্ধারণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp; Example: Afroza <strong>works</strong> in a bank.</span></span><a name=\"_heading=h.wzr32jpr3tiw\"></a><a name=\"_heading=h.b48owilg1jra\"></a> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আফরোজা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যাংকে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">চাকরি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করে ।&nbsp;&nbsp;</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><a name=\"_heading=h.vj1ffzl5kb7q\"></a><strong><span style=\"font-size:14.0pt\"><span style=\"color:black\">Non-finite Verb</span></span></strong></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Subject (Nominative), Number, Tense </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">অনুযায়ী</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যে</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> Verb-</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">রূপ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পরিবর্তন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">তাকে</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Non-finite </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">(</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">অসমাপিকা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ক্রিয়া</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">) </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">বলে।</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">. Non-finite verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">কখনো</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> main verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না।</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Non-finite verb </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সাধারণত</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">adjective </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">অথবা</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">adverb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসেবে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কাজ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কিন্তু</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসেবে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নয়।</span></span>&nbsp;&nbsp;</span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">যেমন /</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> such as: They came to us running. </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">তারা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">দৌড়ে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আমাদের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কাছে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আসে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><strong><span style=\"font-size:14.0pt\"><span style=\"color:black\">Action verb</span></span></strong></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Action verb, Subject </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কাজকে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বর্ণনা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করে।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যেকোন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কাজকেই</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">action verb</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসেবে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বিবেচনা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করা</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">যায়।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Example</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp;○ I&rsquo;ll do my work.</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আমি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আমার</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কাজ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করব।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp;○ She watches TV.</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তিনি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">টিভি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">দেখছেন ।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><u><span style=\"color:black\">Action verbs are of two types</span></u></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp;1. Transitive verbs</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp;2. Intransitive verbs</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">1. Transitive Verb</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">যে</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> Verb-</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">টি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">একা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কোনো</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রকাশ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">তাকে</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Transitive Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">(</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সকর্মক</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ক্রিয়া</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">) </span></span><span style=\"color:black\">বলে।</span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যেমন</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">: </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Rahim wants / </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">রহিম</span></span> <span style=\"color:black\">চায়</span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">।</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\"> এই</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">মাধ্যমে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পূর্ণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থটি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রকাশ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পাচ্ছে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রশ্ন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">রয়ে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যাচ্ছে।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পূর্ণ</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রকাশের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">জন্য</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Object </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যবহার</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রয়োজন</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">।</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">Transitive verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সবসময়</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">একটি</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">direct object </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">দাবি</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">করে।</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Direct object </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আসলে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যটি</span></span> </span></span><span style=\"font-size:16px\">অসম্পূর্ণ&nbsp;</span><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">মনে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সেই</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যে</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> transitive verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যবহৃত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">2. Intransitive Verb</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">যে</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">অন্য</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কোনো</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Word </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সাহায্য</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ছাড়াই</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">একটি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পূর্ণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রকাশ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারে</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">তাকে</span></span><span style=\"font-size:20px\"> <span style=\"color:black\">Intransitive </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">(</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">অকর্মক</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ক্রিয়া</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">) </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">বলে।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যেমন</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">: Dog barks /&nbsp; </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">কুকুর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ঘেউ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ঘেউ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করে । </span></span>&nbsp;<span style=\"font-size:12.0pt\"><span style=\"color:black\">এই</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যের</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পূর্ণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থ</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রকাশ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারছে।</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\"><span style=\"font-size:20px\">Intransitive verb</span> </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কোন</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">object </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রয়োজন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তারা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নিজে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নিজেই</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্য</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পূর্ণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারে।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><strong><span style=\"font-size:14.0pt\"><span style=\"color:black\">Auxiliary Verb</span></span></strong></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Auxiliary Verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হচ্ছে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সাহায্যকারী</span></span> <span style=\"font-size:20px\"><span style=\"color:black\">verb</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তাদের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নিজস্ব</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কোন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পূর্ণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">থাকলেও</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যাকরণগত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">দিক</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">থেকে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">গঠণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নির্মানে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তাদের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">গুরুত্বপূর্ণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ভূমিকা</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">রয়েছে।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">auxiliary verbs are two types / auxiliary verbs <span style=\"font-size:16px\">দু</span></span></span><span style=\"font-size:16px\"><span style=\"color:black\">,প্রকার</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">1 Primary auxiliary</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Have, Do</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এবং</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Be, Primary auxiliary</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসাবে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পরিচিত</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Have</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Have, has, had, having, have not, has not, had not.</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Do</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Do, does, done, to do, did, did not, does not, etc.</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Be</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">Am, is, are, was, were, be, to be, been, was not, were not, etc.</span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">2 Modal Auxiliary</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Modal Auxiliary </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সাধারণত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">মুল</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অর্থকে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রভাবিত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কিন্তু</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তারাও</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">সাহায্যকারী</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসেবেই</span></span> </span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যবহৃত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়।</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">Shall, should, can, could, may, might, ought, ought to, will, would, must, </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\"><span style=\"font-size:20px\">etc</span>. are known as modal auxiliary verbs.</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">Example</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp; ○ He can come home tomorrow</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">.</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তিনি</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আগামীকাল</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাড়িতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আসতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারেন।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp; ○ You should not run in the sun.</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">রোদে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">দৌড়ানো</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">উচিত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নয়।</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:20px\"><span style=\"color:black\">verb</span> </span><span style=\"font-size:12.0pt\"><span style=\"color:black\">অধ্যায়</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">থেকে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">প্রতিটি</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\"><span style=\"font-size:20px\">verb</span> </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সম্পর্কে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ভালোভাবে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বুঝতে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পারলেও</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ভয়ের</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কোন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কারণ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">নেই</span></span> <span style=\"font-size:20px\"><span style=\"color:black\">tense</span> </span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">অধ্যায়</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">পড়া</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">আরম্ভ</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">করলে</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\"><span style=\"font-size:20px\">auxiliary verb</span> </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">সহ অন্যান্য </span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">verb</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\"> সম্পর্কেও আরো ভালো ধারণা পাওয়া </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">যাবে<a name=\"_Hlk165717439\">।</a></span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><strong><span style=\"font-size:14.0pt\"><span style=\"color:black\">Linking verbs</span></span></strong></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">কোন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বাক্যে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যদি</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">primary auxiliary verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যতীত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">অন্য</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">কোন</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">থাকে,</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তাহলে </span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">primary auxiliary </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:#111111\">ঐ</span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\"> বাক্যে</span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\"> main verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসেবে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">ব্যবহৃত</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হয়।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তখন</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">তাকে</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">লিংকিং</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">বলে।</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">যখন প্রাইমারি </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">auxiliary verb </span></span><span style=\"font-size:12.0pt\"><span style=\"color:black\">কোন বাক্যে </span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">main verb</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">হিসেবে ব্যবহৃত হয় এবং উক্ত বাক্যে অন্য কোন</span></span> <span style=\"font-size:14.0pt\"><span style=\"color:black\">verb</span></span> <span style=\"font-size:12.0pt\"><span style=\"color:black\">না </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">থাকে তখন </span></span><span style=\"font-size:14.0pt\"><span style=\"color:black\">primary auxiliary verb</span></span> <a name=\"_Hlk165730575\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">এর</span></span></a><span style=\"font-size:12.0pt\"><span style=\"color:black\"> নিজস্ব অর্থ থাকে যেমন</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:12.0pt\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span style=\"font-size:20px\"> &nbsp; &nbsp; Am, is are = </span><span style=\"font-size:16px\">হয়</span></span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Was, were = </span></span></span><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">ছিল</span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Have been, has been = </span></span></span><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\"><a name=\"_Hlk165731332\">হয়ে</a>ছে</span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Had been = </span></span></span><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">হয়েছিল</span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Will be = </span></span></span><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">হবে </span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp; Will have = </span></span></span><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">থাকবে</span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\"><span style=\"color:black\">&nbsp;Example</span></span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in\"><spa